/// instance over the same file resumes unsealed (I5/E5 — the seal is
/// per-run, not per-file-forever).
///
/// Late-write policy (the ticket's open question, resolved): drop + warn —
/// exactly ONE warning per writer class (message, `custom:<type>`,
/// compaction, …) through [onLateWrite], never a throw into an unhandled
/// zone. A hard failure would retroactively poison a solved trial because
/// of a stray job; the exit code stays the turn's terminal outcome
/// (issue #413 semantics untouched).
final class SessionSeal {
  SessionSeal({this.onLateWrite});

  /// Where the one-per-class warnings go. The CLI wires its diagnostics
  /// channel (stderr on headless hosts); null degrades to a silent drop.
  /// The sink is invoked synchronously inside the rejecting writer's call
  /// stack and is GUARDED: a throwing sink is swallowed (the drop already
  /// happened) so I1's no-throw guarantee holds regardless of sink health.
  final void Function(String message)? onLateWrite;

  DateTime? _sealedAt;

  /// The writer classes already warned about — the "exactly one loud
  /// warning each class" dedupe set.
  final Set<String> _warnedClasses = {};

  /// Whether the seal is closed.
  bool get isSealed => _sealedAt != null;

  /// When the seal closed (null while open).
  DateTime? get sealedAt => _sealedAt;

  /// Seals the session. Idempotent: the first call wins, later calls (and
  /// their sinks) are no-ops.
  void seal() => _sealedAt ??= DateTime.now();

  /// Reports a late write of [writerClass] against a closed seal: drops
  /// nothing itself (the caller skips the append), warns once per class.
  void rejectWrite(String writerClass) {
    if (!isSealed) return;
    if (!_warnedClasses.add(writerClass)) return;
    final sink = onLateWrite;
    if (sink == null) return;
    final at = _sealedAt;
    try {
      sink(
        'session sealed${at == null ? '' : ' at ${at.toIso8601String()}'} — '
        'dropped late write ($writerClass): the session JSONL is immutable '
        'for this process (gh-1589)',
      );
    } on Object {
      // The drop already happened; a sick sink must never replace it with
      // a throw into the late-write caller's stack (I1).
    }
  }
}

  /// or a task-job completion — does BOOKKEEPING only. No `_startRun`, no
  /// model request, no message append: a post-drain reaction run nobody
  /// waits for is exactly the 65gGW7b late-write burst this card closes.
  /// REPL-only `_exited` deliberately stays untouched (different exit
  /// semantics); the fence is headless wrap-up state. The fence is
  /// per-RUN like the seal itself (I5): [runHeadless] resets it at entry
  /// so a second headless run on the same instance (a wake/continuation
  /// loop, a test harness reusing one CLI) never silently inherits a
  /// permanently raised fence — mid-drain settles would do bookkeeping
  /// only and the drain's reaction runs would never start.
  bool _reactionRunsSealed = false;

  /// Set when the user interrupts (Esc/Ctrl-C); the TUI drain loop discards
  /// queued messages instead of starting new turns after an abort.
  var _abortRequested = false;
  Future<void> _settled = Future<void>.value();

  /// The pending approval-prompt answer, if a tool call is waiting on the
  /// user. While set, [_handleLine] routes typed lines here instead of
  /// steering them into the agent.
  Completer<String>? _pendingApprovalAnswer;

  /// The pending ask-menu input line, if an `ask` tool call is waiting on
  /// the user. Unlike the approval prompt, EMPTY lines are routed here too:
  /// empty input is the menu's free-text affordance. Completes with `null`
  /// on cancel (Ctrl-C, input shutdown).
  Completer<String?>? _pendingAskAnswer;

  /// The pending CLI-prompt input line, if a guided flow (the custom
  /// provider setup) is waiting on a free-form answer. Like the ask routing,

[761 more lines in file. Use offset=1600 to continue.]

    bool waitForJobs = false,
    StreamJsonWriter? streamJson,
  }) async {
    _hep = hep;
    // gh-1589 (review): the settle→reaction fence is per-RUN state (I5 —
    // the same per-run semantics as the seal). Reset it at entry, before
    // the prompt drive, so a second runHeadless on this instance (a
    // wake/continuation loop, a test harness reusing one CLI) starts
    // unsealed: a fence inherited from the previous run's wrap-up would
    // drop this run's mid-drain settles to bookkeeping only, silently.
    _reactionRunsSealed = false;
    // The [net] retry voice reaches headless too (issue #1121): the bench
    // runs `fa -p`, and retries that stayed silent there made a
    // connect-stall death indistinguishable from a no-retry one in the
    // trial artifacts.
    _wireTransientRetryNotice();
    // Cube cache restore, mirroring [run]'s boot (the headless run sees the
    // same cached trees a REPL session would).
    await _cubeBootRestore();
    _session = await _initializeSession();
    // Ownership lease (#428, E7): a headless run NEVER spawns a second
    // writer over a live lease — it refuses with the banner (exit 3) so
    // wake loops reopen interactively instead of fighting the owner.
    // Restart honesty (issue #450): detached jobs from the previous run.
    await _waiting.captureLostJobs();

