  final jobs = <_SealJob>[];

  @override
  bool get backgroundJobsSupported => true;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) async => Err(
    ExecutionError(
      ExecutionErrorCode.shellUnavailable,
      'No shell is available in this environment',
