  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  }) async {
    final job = _SealJob(id: id, command: command, logPath: logPath);
    jobs.add(job);
    return Ok(job);
  }
